import sys

def cutsky_ic_ABACUS(args, galtype=None, redshift=None, snapshot=None):    
    cpus = int(os.environ.get("SLURM_CPUS_PER_TASK", 6))
    in_fol_temp = "AbacusSummit_base_c000_ph"

    config_file = f"./ABACUS/config/config_ABACUS_ic_LRG_HFDR2_v2.ini"
    cosmo='000'
    basetag='ic'
    ######### Instances
#    lightcone_instance = LightCone(config_file, args)
    survey_geometry_instance = SurveyGeometry(config_file, args, galtype=galtype)

    # ######### CutSky
    for i in range(1,25):
        phase = str(int(i)).zfill(3)

        #in_part_path = 'y1/' #f"/{in_fol_temp}{phase}/"
        in_part_path = f"/{in_fol_temp}{phase}/"
        input_name = "IC_real_space.sub{subbox}.fits.gz"

        out_part_path = f"{in_fol_temp}{phase}/"		
        output_name = "ic_snap{snapshot}_ph" + phase + "_shell_{shellnum}.hdf5"
        
        path_instance = Paths(config_file, args, input_name, out_part_path, output_name, phase=phase, cosmo=cosmo, basetag=basetag, snapshot=snapshot, rea=i)

        lightcone_instance = LightCone(config_file, args, cosmoprimo=path_instance.return_cosmoprimo(), cosmo=cosmo)
#        path_instance = Paths(config_file, args, in_part_path, input_name, out_part_path, output_name)
        lightcone_instance.generate_shells(path_instance, redshift=snapshot, cutsky=True, nproc=cpus, n_subboxes=64, cat_seed=i, phase=phase)
#        lightcone_instance.generate_shells(path_instance, snapshot=snapshot, redshift=redshift, cutsky=True, nproc=64, n_subboxes=64, cat_seed=i)

        survey_geometry_instance.shell(path_instance, nproc=cpus, todo=3)

        out_fits = os.path.join(path_instance.dir_out, f"cutsky_ic_{in_fol_temp}{phase}.fits")

        stack_shells(survey_geometry_instance, inpath=path_instance.shells_out_path, out_file=out_fits, mock_random_ic="ic", ngc_sgc_tot="TOT", seed=i)

def cutsky_ic_ABACUS_array(args, galtype=None, redshift=None, snapshot=None, rea=0):    
    cpus = int(os.environ.get("SLURM_CPUS_PER_TASK", 6))
    in_fol_temp = "AbacusSummit_base_c000_ph"

    config_file = f"./ABACUS/config/config_ABACUS_ic_LRG_HFDR2_v2.ini"
    cosmo='000'
    basetag='ic'
    ######### Instances
#    lightcone_instance = LightCone(config_file, args)
    survey_geometry_instance = SurveyGeometry(config_file, args, galtype=galtype)

    # ######### CutSky
    #for i in range(1,25):
    phase = str(int(rea)).zfill(3)

        #in_part_path = 'y1/' #f"/{in_fol_temp}{phase}/"
    in_part_path = f"/{in_fol_temp}{phase}/"
    input_name = "IC_real_space.sub{subbox}.fits.gz"

    out_part_path = f"{in_fol_temp}{phase}/"		
    output_name = "ic_snap{snapshot}_ph" + phase + "_shell_{shellnum}.hdf5"
        
    path_instance = Paths(config_file, args, input_name, out_part_path, output_name, phase=phase, cosmo=cosmo, basetag=basetag, snapshot=snapshot, rea=rea)

    lightcone_instance = LightCone(config_file, args, cosmoprimo=path_instance.return_cosmoprimo(), cosmo=cosmo)
#        path_instance = Paths(config_file, args, in_part_path, input_name, out_part_path, output_name)
    lightcone_instance.generate_shells(path_instance, redshift=snapshot, cutsky=True, nproc=cpus, n_subboxes=64, cat_seed=i, phase=phase)
#        lightcone_instance.generate_shells(path_instance, snapshot=snapshot, redshift=redshift, cutsky=True, nproc=64, n_subboxes=64, cat_seed=i)

    survey_geometry_instance.shell(path_instance, nproc=cpus, todo=3)

    out_fits = os.path.join(path_instance.dir_out, f"cutsky_ic_{in_fol_temp}{phase}.fits")

    stack_shells(survey_geometry_instance, inpath=path_instance.shells_out_path, out_file=out_fits, mock_random_ic="ic", ngc_sgc_tot="TOT", seed=i)






